def TXQ(k, title, story, amt, sol, labs, three, build=None):
    """One transaction in its own sheet: the event, then three revealed notes (assets, liabilities, equity), then the totals and the check."""
    d = {'A1': 'סכום העסקה', 'B1': amt, 'A3': 'פריט', 'B3': 'נכסים (A)', 'C3': 'התחייבויות (L)', 'D3': 'הון עצמי (E)', 'A4': labs[0], 'A5': labs[1], 'A6': 'סך השינוי', 'A7': 'בדיקה: A פחות L פחות E'}
    s = {**sol, 'B6': '=SUM(B4:B5)', 'C6': '=SUM(C4:C5)', 'D6': '=SUM(D4:D5)', 'B7': '=B6-C6-D6'}
    first = list(sol)
    QX(f'x-t{k}', f'עסקה {k}', title, [story, '<b>נדרש:</b> איך העסקה משנה את הנכסים, את ההתחייבויות ואת ההון העצמי? האם המשוואה נשארת מאוזנת?'],
       'הזינו את סכום העסקה ב-B1. בשורות 4 ו-5: השינוי בעמודה הנכונה, כהפניה ל-B1 (עם מינוס כשהפריט קטן). שורה 6: סך השינוי בכל עמודה. B7: הבדיקה.',
       d, s, [150, 100, 110, 100], [3], fmt={a: 'num0' for a in ['B1', 'B4', 'B5', 'C4', 'C5', 'D4', 'D5', 'B6', 'C6', 'D6', 'B7']},
       hints=['קודם שואלים: איזה פריט משתנה, והאם הוא נכס, התחייבות או הון. כותבים =B1 בעמודה שלו, או =-B1 אם הוא קטן.', 'סיכום עמודה: =SUM(B4:B5). הבדיקה: =B6-C6-D6, וצריך לצאת 0.'],
       remind='=SUM(B4:B5)   =B6-C6-D6', partial=first[:1],
       steps=[dict(cells={a: sol[a]}, note=f'שורת {labs[i]}: בתא {a} כותבים {sol[a]}' + (', כי הפריט קטן.' if sol[a].startswith('=-') else '.')) for i, a in enumerate(first)] + [dict(cells={'B6': '=SUM(B4:B5)', 'C6': '=SUM(C4:C5)', 'D6': '=SUM(D4:D5)', 'B7': '=B6-C6-D6'}, note='סיכום כל עמודה ב-SUM, והבדיקה: =B6-C6-D6 נותן 0. מאוזן.', sel='B6', sel2='D6')],
       note=[('note', x, i + 1) for i, x in enumerate(three)], build=build, zone=[f'{c}{r}' for c in 'BCD' for r in (4, 5)], xtitle=f'עסקה {k}: {title}', done='המשוואה מאוזנת: הבדיקה נותנת 0.')


